mapper.delete:
DELETE FROM crm_customer_identity
WHERE contact_id = #{contactId}
  AND identity_type = #{identityType}
  AND identity_value = #{identityValue}

mapper.update:
UPDATE crm_customer_identity
SET contact_id = #{targetContactId}
WHERE contact_id = #{sourceContactId}
  AND (identity_type, identity_value) NOT IN (
    SELECT identity_type, identity_value FROM crm_customer_identity
    WHERE contact_id = #{targetContactId}
  )

UPDATE crm_customer_identity
SET is_primary = true, update_time = now()
WHERE contact_id = #{contactId}
  AND identity_type = #{identityType}
  AND identity_value = #{identityValue}
